// Find the folder for this project across every parent folder searched.
const projectId = String($('Execute Workflow Trigger').first().json.projectId || '').trim();

// Track which input item each folder came from, to keep pairedItem honest.
const folders = [];
$input.all().forEach((item, i) => {
  (item.json.value || []).forEach((f) => folders.push({ folder: f, source: i }));
});

// Bounded match instead of a bare includes(): plain substring matching lets
// project 17540-1 match the folder for 17540-10.
const escaped = projectId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const re = new RegExp(`(^|[^0-9A-Za-z-])${escaped}([^0-9A-Za-z-]|$)`);
const matches = folders.filter(({ folder }) => re.test((folder.displayName || '').trim()));

if (matches.length === 0) {
  return [{ json: { folderFound: false, projectId, matchCount: 0 }, pairedItem: 0 }];
}

// Emit exactly ONE item even when the folder exists under both Ongoing and
// Completed. Returning every match made the rest of the flow run once per
// match and POST two callbacks for the same job_id.
const best = matches[0];

return [{
  json: {
    folderFound: true,
    folderId: best.folder.id,
    folderName: (best.folder.displayName || '').trim(),
    projectId,
    matchCount: matches.length,
    allMatches: matches.map((m) => ({ id: m.folder.id, name: (m.folder.displayName || '').trim() }))
  },
  pairedItem: best.source
}];

// Decide which mailbox + root folder to search, or fail with an explicit code.
// Fails loudly rather than guessing: every error code below is surfaced in the
// dashboard as `entry.error_code`.

const GENERAL_MAILBOX = 'projektmanagement@exposeprofi.de';
const GENERAL_PM_NAME = 'Aliyu';
const GENERAL_FOLDER_ID = 'AAMkADVhNmE4OTBjLTVmZDYtNDhkNy04N2M5LTQ5NTM4ZTQyN2EyNwAuAAAAAACFo3t7TtrDT4FZaz0FwuiiAQDYtPTRVWhpSb_tzzT0WBqAAAL739y4AAA=';

const projectRow = $('Get Project (Supabase)1').first().json;
const pmType = (projectRow.pm_type ?? '').trim();
const rawName = (projectRow.project_manager ?? '').trim();

const fail = (error, message, extra = {}) => ({
  pmResolutionFailed: true,
  error,
  message,
  debug: { pm_type: pmType, project_manager: rawName, ...extra }
});

// GENERAL projects: fixed shared mailbox + folder, no name matching at all.
// (projects.pm_type is a Postgres enum with exactly 'general' | 'dedicated'.)
if (pmType === 'general') {
  return {
    pmResolutionFailed: false,
    isGeneral: true,
    project_manager: GENERAL_PM_NAME,
    pm_email: GENERAL_MAILBOX,
    folder_id: GENERAL_FOLDER_ID,
    debug: {
      pm_type: pmType,
      note: 'General project - using the shared projektmanagement mailbox, name matching skipped.'
    }
  };
}

// --- dedicated projects: resolve the PM first name against users ------------

if (!rawName || /^unknown$/i.test(rawName)) {
  return fail(
    'PM_NAME_UNKNOWN',
    'This project has no usable project manager (projects.project_manager is empty or "unknown"), so there is no mailbox to read.'
  );
}

// Shared assignments ('Viktoria & Sonia', 'Sonia und Vivien', ...) name two
// people and therefore two mailboxes. Refuse rather than silently picking one.
if (/\s(?:&|und)\s/i.test(rawName)) {
  return fail(
    'PM_SHARED_ASSIGNMENT',
    `"${rawName}" names more than one project manager - cannot decide which mailbox to read. Split the assignment or set pm_type='general'.`
  );
}

// alwaysOutputData means a no-match run still emits one empty item - drop it.
const rows = $input.all().map((item) => item.json).filter((r) => r && r.id);
const matches = rows.filter((r) => r.role === 'pm' && !r.deleted_at);

const debugInfo = {
  pm_type: pmType,
  searched_for_first_name: rawName,
  rows_returned: rows.length,
  matched_count: matches.length,
  matched: matches.map((r) => ({ id: r.id, email: r.email, role: r.role }))
};

if (matches.length === 0) {
  return fail(
    'PM_NOT_FOUND',
    `No active user with role='pm' has the first name "${rawName}". Check for a typo in projects.project_manager or a missing users row.`,
    debugInfo
  );
}

if (matches.length > 1) {
  return fail(
    'PM_NAME_AMBIGUOUS',
    `Multiple PMs share the first name "${rawName}" - cannot safely determine which mailbox to use. Manual resolution required.`,
    debugInfo
  );
}

const pm = matches[0];

// Most users still have a NULL project_folder_id. Catch it here instead of
// building a Graph URL with an empty folder segment.
if (!pm.project_folder_id) {
  return fail(
    'PM_FOLDER_NOT_CONFIGURED',
    `${pm.email} has no project_folder_id set, so there is no mailbox folder to search. Populate users.project_folder_id for this PM.`,
    debugInfo
  );
}

return {
  pmResolutionFailed: false,
  isGeneral: false,
  user_id: pm.id,
  project_manager: rawName,
  pm_email: pm.email,
  folder_id: pm.project_folder_id,
  debug: debugInfo
};

// Carry the token, the resolved mailbox and the PM's root project folder
// together, so every downstream Graph call can read all three from one place.
const pm = $('Check PM Match Count1').first().json;

return {
  access_token: $json.access_token,
  mailbox_email: pm.pm_email,
  root_folder_id: pm.folder_id
};

// One item per parent folder (Ongoing / Completed / ...), so all of them get
// searched for the project folder rather than only the first.
const folders = $input.first().json.value || [];
const ctx = $('Combine Token + Mailbox1').first().json;

// No sub-folders under the PM's root: still emit one item so the flow reaches
// "Folder Found?" and sends a PROJECT_FOLDER_NOT_FOUND callback instead of
// ending silently and leaving the brief stuck on 'processing'.
if (folders.length === 0) {
  return [{
    parentFolderId: ctx.root_folder_id,
    parentFolderName: '(root)',
    mailbox_email: ctx.mailbox_email,
    access_token: ctx.access_token
  }];
}

return folders.map((f) => ({
  parentFolderId: f.id,
  parentFolderName: f.displayName,
  mailbox_email: ctx.mailbox_email,
  access_token: ctx.access_token
}));

const messages = $input.all().flatMap((item) => item.json.value || []);

const trigger = $('Execute Workflow Trigger').first().json;
const projectRow = $('Get Project (Supabase)1').first().json;
const pm = $('Check PM Match Count1').first().json;

const projectId = trigger.projectId;
// FIXED: this used projects.project_manager and labelled it the project name.
const projectName = projectRow.project_name || '(no project name)';
const mailbox = pm.pm_email;

let md = `# Email Thread Export - Project ${projectId} (${projectName})\n`;
md += `Exported: ${new Date().toISOString()}\n`;
md += `Total messages: ${messages.length}\n`;
md += `Mailbox: ${mailbox}\n\n---\n\n`;

messages.forEach((msg, index) => {
  const date = new Date(msg.sentDateTime).toISOString().replace('T', ' ').substring(0, 16);
  const from = msg.from?.emailAddress?.address || 'Unknown';
  const to = (msg.toRecipients || []).map((r) => r.emailAddress.address).join(', ') || '-';
  const cc = (msg.ccRecipients || []).map((r) => r.emailAddress.address).join(', ') || '-';
  const attachFlag = msg.hasAttachments ? '\n*(Attachments present but not exported)*' : '';

  let body = msg.body?.content || '';
  if (msg.body?.contentType === 'html') {
    body = body
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<[^>]*>?/gm, ' ')
      .replace(/&nbsp;/g, ' ')
      .replace(/\s+\n/g, '\n')
      .replace(/[ \t]{2,}/g, ' ');
  }

  md += `## ${index + 1}. [${date}] Subject: ${msg.subject || '(no subject)'}\n`;
  md += `**From:** ${from}\n**To:** ${to}\n**Cc:** ${cc}${attachFlag}\n\n`;
  md += `${body.trim()}\n\n---\n\n`;
});

return {
  thread_markdown: md,
  thread_base64: Buffer.from(md, 'utf-8').toString('base64'),
  email_count: messages.length,
  earliest: messages[0]?.sentDateTime || null,
  latest: messages[messages.length - 1]?.sentDateTime || null,
  project_name: projectName,
  mailbox,
  filename: `${projectId}_email_thread_${new Date().toISOString().split('T')[0]}.md`
};

// Parse the model response, guarding against non-JSON / markdown-fenced output.
const out = $input.first().json;
const raw =
  out?.message?.content ??
  out?.choices?.[0]?.message?.content ??
  '';

const cleaned = String(raw).replace(/```json\s*|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    quick_facts: 'Summary generation returned an unparseable response.',
    key_undocumented_context: cleaned,
    open_questions: '',
    notable_moments: ''
  };
}

return { summary: parsed };

